import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.CVt6dz2a.js";const u=JSON.parse('{"title":"EP.00 学前必备：开跑前的检查清单","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.00-prerequisites.md","filePath":"comics/EP.00-prerequisites.md","lastUpdated":1792595797000}'),r={name:"comics/EP.00-prerequisites.md"};function s(l,e,d,n,p,c){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="ep-00-学前必备-开跑前的检查清单" tabindex="-1">EP.00 学前必备：开跑前的检查清单 <a class="header-anchor" href="#ep-00-学前必备-开跑前的检查清单" aria-label="Permalink to &quot;EP.00 学前必备：开跑前的检查清单&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/00-prerequisites/">0 学前必备：先修知识自查与补课指南</a> 动手演示：<a href="./../public/demos/prerequisites/vector-lab.html">vector-lab 点积叉积实验室</a> · <a href="./../public/demos/prerequisites/vector-lab-3d.html">vector-lab-3d 三维版</a> · <a href="./../public/demos/prerequisites/projection-cube.html">projection-cube 手写透视投影</a> · <a href="./../public/demos/prerequisites/render-pitfalls.html">render-pitfalls 渲染三坑实验室</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君把官网示例存成 html 双击打开——白屏报错，控制台一条 CORS 报错看不懂。</td></tr><tr><td>② 揭秘</td><td>码叔摆出两条硬门槛：读得懂 ES Module 的 JavaScript + 会起本地静态服务器，importmap 只是浏览器的&quot;路径别名&quot;。</td></tr><tr><td>③ 实证</td><td>像素酱担心要啃完线性代数，码叔用两把尺打消顾虑：点积判夹角、叉积求法线，弧度混个脸熟就够。</td></tr><tr><td>④ 结案</td><td>码叔给出渲染常识三件套与坑点清单：三角形拼一切、管线三步走、PBR 要开灯，清单过完再开第一课。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-file-是跨源-es-module-必须跑在-http-s-上" tabindex="-1">① file:// 是跨源：ES Module 必须跑在 http(s) 上 <a class="header-anchor" href="#_1-file-是跨源-es-module-必须跑在-http-s-上" aria-label="Permalink to &quot;① file:// 是跨源：ES Module 必须跑在 http(s) 上&quot;">​</a></h3><p>浏览器把 <code>file://</code> 协议当跨源对待，ES Module 的加载会被 CORS 策略直接拦截，典型报错是 <code>Access to script from origin &#39;null&#39; has been blocked by CORS policy</code>。这不是 bug，是安全设计。解法三选一：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 零配置静态服务器</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或 VSCode 插件 Live Server</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或本教程仓库自带的 pnpm dev</span></span></code></pre></div><h3 id="_2-两条硬门槛与-importmap" tabindex="-1">② 两条硬门槛与 importmap <a class="header-anchor" href="#_2-两条硬门槛与-importmap" aria-label="Permalink to &quot;② 两条硬门槛与 importmap&quot;">​</a></h3><p>学前自查表有 8 项，但<strong>硬性门槛只有两条</strong>：</p><ol><li><strong>JavaScript</strong>：能读懂 <code>import</code>/解构/箭头函数/<code>async</code> 的代码——Three.js 每个示例都是十几行起跳的 ES Module；</li><li><strong>本地静态服务器</strong>：<code>npx serve .</code> 一条命令的事。</li></ol><p>importmap 是浏览器原生的&quot;模块路径别名&quot;，让裸导入 <code>import * as THREE from &#39;three&#39;</code> 能被解析到 CDN 文件；<code>three/addons/</code> 带尾斜杠表示前缀映射。CDN 与 npm 两条路线的 <code>import</code> 语句完全相同，学习期用 CDN、做项目换 npm。</p><h3 id="_3-向量两把尺-点积与叉积" tabindex="-1">③ 向量两把尺：点积与叉积 <a class="header-anchor" href="#_3-向量两把尺-点积与叉积" aria-label="Permalink to &quot;③ 向量两把尺：点积与叉积&quot;">​</a></h3><p>三维图形只用到线性代数的一个小子集，先用两把尺建立直觉（可在 vector-lab 演示里拖出来）：</p><ul><li><strong>点积 A·B</strong>：一个数，等于夹角余弦 × 两长度。<code>&gt;0</code> 同向、<code>=0</code> 垂直、<code>&lt;0</code> 反向——判断&quot;敌人是否在视野内&quot;就是它；</li><li><strong>叉积 A×B</strong>：一个向量，同时垂直于 A、B（右手定则：四指从 A 弯向 B，拇指即方向），模长等于两向量张成的平行四边形面积——求三角形面法线就是它。</li></ul><p>另外记住换算：<strong>180° = Math.PI</strong>，Three.js 所有角度参数都是弧度。</p><h3 id="_4-渲染常识-三角形、管线与-pbr" tabindex="-1">④ 渲染常识：三角形、管线与 PBR <a class="header-anchor" href="#_4-渲染常识-三角形、管线与-pbr" aria-label="Permalink to &quot;④ 渲染常识：三角形、管线与 PBR&quot;">​</a></h3><ol><li>一切 3D 形状都是三角形拼的——一个 BoxGeometry 是 12 个三角形，面数直接决定渲染开销；</li><li>管线三步：<strong>顶点着色器</strong>（算位置）→ <strong>光栅化</strong>（拆像素）→ <strong>片元着色器</strong>（算颜色）；</li><li><code>MeshStandardMaterial</code> 等 PBR 材质用&quot;金属度 + 粗糙度&quot;描述反光，<strong>必须有灯光</strong>才显形——这就是下一话黑屏坑的根源。</li></ol><p>第④格的三个坑（关灯纯黑、忘 <code>scene.add</code>、弧度换算）都可在 <a href="./../public/demos/prerequisites/render-pitfalls.html">render-pitfalls 渲染三坑实验室</a> 里亲手复现：关掉灯光看画面瞬间变黑、取消勾选让绿色魔方&quot;游离&quot;、开线框模式数三角形。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：完全不会 JavaScript，能直接学 Three.js 吗？</strong> 不建议。语言 + 图形 API + 数学三座山同时爬必崩，先花 1–2 周补 JS 语法与异步，再从 EP.01 开始。</li><li><strong>Q：需要先系统啃完线性代数吗？</strong> 不需要。用到哪个讲哪个：本话讲直觉，2.2 进阶篇展开层级矩阵，遇到陌生术语现场查。</li><li><strong>Q：CDN 和 npm 会冲突吗？</strong> 不会，<code>import</code> 语句完全一样。从 CDN 迁到 npm 只需删掉 importmap、<code>pnpm add three</code>。</li><li><strong>Q：new 出来的 Mesh 为什么看不见？</strong> Three.js 只渲染场景树上的节点，忘了 <code>scene.add()</code> 就是&quot;游离在内存里&quot;。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>双击打开含 importmap 的 html 报 CORS 错误，根本原因是什么？至少说出一种解法。</li><li><code>(1,0,0) · (0,1,0)</code> 的值是多少？说明两向量的位置关系。</li><li><code>MeshStandardMaterial</code> 场景没有任何光源，画面是什么样？为什么？</li></ol><details><summary>答案</summary><ol><li><code>file://</code> 协议被浏览器视为跨源，ES Module 加载被 CORS 策略拦截。解法：<code>npx serve .</code> / Live Server / <code>pnpm dev</code> 任一本地静态服务器。</li><li>等于 <strong>0</strong>，两向量互相垂直（点积为 0 即 90° 夹角）。</li><li><strong>纯黑</strong>。PBR 材质靠灯光计算颜色，零光源时输出黑色；改用 MeshBasicMaterial/NormalMaterial 或加一盏 HemisphereLight。</li></ol></details>`,24)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
